<?php
declare(strict_types=1);

namespace Erp\Modules\Purchase;

use Erp\Core\Security\AccessDeniedException;
use Erp\Core\Security\Authorization;
use Erp\Core\Security\UserContext;
use InvalidArgumentException;
use PDO;
use Throwable;

final class PurchaseRepository
{
    public function __construct(private readonly PDO $pdo) {}

    public function options(UserContext $user, Authorization $auth, mixed $rawCompanyId): array
    {
        $companyId = $this->company($user, $auth, $rawCompanyId);
        $company = $this->pdo->prepare('SELECT c.currency_code,cur.decimal_places FROM companies c JOIN currencies cur ON cur.currency_code=c.currency_code WHERE c.id=:company AND c.active=1');
        $company->execute(['company'=>$companyId]);
        $currency = $company->fetch();
        $contacts = $this->pdo->prepare("SELECT id,name,email,phone,supplier_payment_terms_id,payable_account_id FROM contacts WHERE supplier=1 AND active=1 AND (company_id IS NULL OR company_id=:company) ORDER BY name,id");
        $contacts->execute(['company'=>$companyId]);
        $products = $this->pdo->prepare("SELECT p.id,p.name,p.internal_reference,p.category_id,p.product_type,p.uom_id,p.purchase_uom_id,p.cost_price,p.purchase_account_id,u.name AS uom_name,u.abbreviation AS uom_abbreviation,pu.name AS purchase_uom_name,pu.abbreviation AS purchase_uom_abbreviation FROM products p JOIN units_of_measure u ON u.id=p.uom_id JOIN units_of_measure pu ON pu.id=p.purchase_uom_id WHERE p.company_id=:company AND p.active=1 AND p.purchase_ok=1 ORDER BY p.name,p.id");
        $products->execute(['company'=>$companyId]);
        $units = $this->pdo->prepare('SELECT u.id,u.name,u.abbreviation,u.category_id,u.company_id FROM units_of_measure u WHERE u.active=1 AND (u.company_id IS NULL OR u.company_id=:company) AND EXISTS (SELECT 1 FROM uom_categories c WHERE c.id=u.category_id AND c.active=1 AND (c.company_id IS NULL OR c.company_id=:category_company)) ORDER BY u.name,u.id');
        $units->execute(['company'=>$companyId,'category_company'=>$companyId]);
        $warehouses = $this->pdo->prepare('SELECT id,name,code FROM warehouses WHERE company_id=:company AND active=1 ORDER BY name,id');
        $warehouses->execute(['company'=>$companyId]);
        $buyers = $this->pdo->prepare("SELECT u.id,c.name FROM users u JOIN contacts c ON c.id=u.contact_id JOIN user_company_access uc ON uc.user_id=u.id WHERE uc.company_id=:company AND u.status IN ('confirmed','active') ORDER BY c.name,u.id");
        $buyers->execute(['company'=>$companyId]);
        $terms = $this->pdo->prepare('SELECT id,name,due_days FROM payment_terms WHERE active=1 AND (company_id IS NULL OR company_id=:company) ORDER BY name,id');
        $terms->execute(['company'=>$companyId]);
        $taxes = $this->pdo->prepare('SELECT t.id,t.name,t.amount,t.price_included,t.account_id,a.code AS account_code,a.name AS account_name FROM purchase_taxes t LEFT JOIN accounting_accounts a ON a.id=t.account_id WHERE t.company_id=:company AND t.active=1 ORDER BY t.name,t.id');
        $taxes->execute(['company'=>$companyId]);
        $accounts = $this->pdo->prepare('SELECT id,code,name,account_type FROM accounting_accounts WHERE company_id=:company AND active=1 ORDER BY code,id');
        $accounts->execute(['company'=>$companyId]);
        $journals = $this->pdo->prepare("SELECT id,code,name FROM accounting_journals WHERE company_id=:company AND active=1 AND journal_type='purchase' ORDER BY name,id");
        $journals->execute(['company'=>$companyId]);
        $paymentJournals = $this->pdo->prepare("SELECT j.id,j.code,j.name,j.default_account_id,j.outstanding_payments_account_id,j.outstanding_receipts_account_id FROM accounting_journals j WHERE j.company_id=:company AND j.active=1 AND j.journal_type IN ('bank','cash') AND j.default_account_id IS NOT NULL AND (j.outstanding_payments_account_id IS NOT NULL OR j.outstanding_receipts_account_id IS NOT NULL) ORDER BY j.name,j.id");
        $paymentJournals->execute(['company'=>$companyId]);
        return ['company_id'=>$companyId,'currency_code'=>$currency['currency_code']??null,'decimal_places'=>(int)($currency['decimal_places']??2),
            'suppliers'=>$contacts->fetchAll(),'products'=>$products->fetchAll(),'units'=>$units->fetchAll(),'warehouses'=>$warehouses->fetchAll(),'buyers'=>$buyers->fetchAll(),
            'payment_terms'=>$terms->fetchAll(),'taxes'=>$taxes->fetchAll(),'accounts'=>$accounts->fetchAll(),
            'purchase_journals'=>$journals->fetchAll(),'payment_journals'=>$paymentJournals->fetchAll(),
            'contracts'=>$auth->allowsForCompany('contracts.read',$companyId)?(new \Erp\Modules\Contracts\ContractRepository($this->pdo))->orderOptions($companyId,'supplier'):[],
            'bill_control_policies'=>[['value'=>'ordered','name'=>'Ordered quantities'],['value'=>'received','name'=>'Received quantities']]];
    }

    public function search(UserContext $user, Authorization $auth, array $filters): array
    {
        $companyId=$this->company($user,$auth,$filters['company_id']??null);
        $statusCounts=['draft'=>0,'sent'=>0,'purchase'=>0,'cancelled'=>0];
        $statusQuery=$this->pdo->prepare('SELECT state,COUNT(*) AS total FROM purchase_orders WHERE company_id=:company GROUP BY state');
        $statusQuery->execute(['company'=>$companyId]);
        foreach($statusQuery->fetchAll() as $statusRow)if(array_key_exists($statusRow['state'],$statusCounts))$statusCounts[$statusRow['state']]=(int)$statusRow['total'];
        $where=['po.company_id=:company'];$params=['company'=>$companyId];
        $state=(string)($filters['state']??'all');
        if($state!=='all'){if(!in_array($state,['draft','sent','purchase','cancelled'],true))throw new InvalidArgumentException('Select a valid Purchase order status.');$where[]='po.state=:state';$params['state']=$state;}
        if(($filters['partner_contact_id']??'')!==''){$where[]='po.partner_contact_id=:partner';$params['partner']=$this->positiveId($filters['partner_contact_id'],'Supplier Contact');}
        $text=trim((string)($filters['q']??''));
        if($text!==''){if(mb_strlen($text)>190)throw new InvalidArgumentException('Purchase search must be 190 characters or fewer.');$like='%'.str_replace(['!','%','_'],['!!','!%','!_'],$text).'%';$where[]='(po.name LIKE :name_q OR po.vendor_reference LIKE :reference_q OR c.name LIKE :vendor_q)';$params+=['name_q'=>$like,'reference_q'=>$like,'vendor_q'=>$like];}
        $clause=implode(' AND ',$where);$count=$this->pdo->prepare('SELECT COUNT(*) FROM purchase_orders po JOIN contacts c ON c.id=po.partner_contact_id WHERE '.$clause);$count->execute($params);
        $limit=max(1,min(100,(int)($filters['limit']??50)));$offset=max(0,min(1000000,(int)($filters['offset']??0)));
        $activitiesCount=$auth->allowsForCompany('todo.read',$companyId)?'(SELECT COUNT(*) FROM todo_tasks tt JOIN todo_stages ts ON ts.id=tt.stage_id AND ts.company_id=tt.company_id AND ts.stage_type=\'open\' WHERE tt.company_id=po.company_id AND tt.source_model=\'purchase.order\' AND tt.source_record_id=po.id AND tt.archived_at IS NULL) AS activities_count':'0 AS activities_count';
        $query=$this->pdo->prepare('SELECT po.id,po.company_id,po.name,po.partner_contact_id,c.name AS supplier_name,co.name AS company_name,po.contract_id,contract.name AS contract_name,po.buyer_user_id,buyer.name AS buyer_name,po.currency_code,po.order_date,po.order_deadline,po.expected_arrival,po.arrival_confirmation,po.vendor_reference,po.bill_control_policy,po.three_way_match,po.state,po.untaxed_amount,po.tax_amount,po.total_amount,'.$activitiesCount.' FROM purchase_orders po JOIN companies co ON co.id=po.company_id JOIN contacts c ON c.id=po.partner_contact_id LEFT JOIN contracts contract ON contract.id=po.contract_id AND contract.company_id=po.company_id LEFT JOIN users u ON u.id=po.buyer_user_id LEFT JOIN contacts buyer ON buyer.id=u.contact_id WHERE '.$clause.' ORDER BY po.order_date DESC,po.id DESC LIMIT :limit OFFSET :offset');
        foreach($params as $key=>$value)$query->bindValue(':'.$key,$value,is_int($value)?PDO::PARAM_INT:PDO::PARAM_STR);$query->bindValue(':limit',$limit,PDO::PARAM_INT);$query->bindValue(':offset',$offset,PDO::PARAM_INT);$query->execute();
        return ['records'=>$query->fetchAll(),'total'=>(int)$count->fetchColumn(),'company_id'=>$companyId,'status_counts'=>$statusCounts,'limit'=>$limit,'offset'=>$offset];
    }

    public function find(int $id, UserContext $user, Authorization $auth): ?array
    {
        $q=$this->pdo->prepare('SELECT po.*,c.name AS supplier_name,c.email AS supplier_email,c.phone AS supplier_phone,c.payable_account_id,c.supplier_payment_terms_id,c.supplier_currency_code,buyer.name AS buyer_name,w.name AS warehouse_name,pt.name AS payment_terms_name,contract.name AS contract_name FROM purchase_orders po JOIN contacts c ON c.id=po.partner_contact_id LEFT JOIN contracts contract ON contract.id=po.contract_id AND contract.company_id=po.company_id LEFT JOIN users u ON u.id=po.buyer_user_id LEFT JOIN contacts buyer ON buyer.id=u.contact_id LEFT JOIN warehouses w ON w.id=po.warehouse_id LEFT JOIN payment_terms pt ON pt.id=po.payment_terms_id WHERE po.id=:id');$q->execute(['id'=>$id]);$order=$q->fetch();
        if(!$order||!$auth->canAccessCompany((int)$order['company_id']))return null;
        $lines=$this->pdo->prepare('SELECT pol.*,p.name AS product_name,p.product_type,p.tracking,p.purchase_account_id,u.name AS uom_name,u.abbreviation AS uom_abbreviation,pt.account_id AS tax_account_id,(SELECT COALESCE(SUM(CASE WHEN sm.return_of_move_id IS NULL THEN sm.done_quantity ELSE 0-sm.done_quantity END),0) FROM stock_moves sm WHERE sm.source_line_model=\'purchase_order_line\' AND sm.source_line_id=pol.id AND sm.state=\'done\') AS received_quantity,(SELECT COALESCE(SUM(vbl.quantity),0) FROM vendor_bill_lines vbl JOIN vendor_bills vb ON vb.id=vbl.bill_id WHERE vbl.purchase_order_line_id=pol.id AND vb.state IN (\'draft\',\'posted\')) AS billed_quantity FROM purchase_order_lines pol JOIN products p ON p.id=pol.product_id JOIN units_of_measure u ON u.id=pol.uom_id LEFT JOIN purchase_taxes pt ON pt.id=pol.tax_id WHERE pol.order_id=:order_id ORDER BY pol.sequence,pol.id');$lines->execute(['order_id'=>$id]);$order['lines']=$lines->fetchAll();
        $receipts=$this->pdo->prepare('SELECT sm.id,sm.reference,sm.product_id,p.name AS product_name,sm.demand_quantity,sm.done_quantity,sm.state,sm.scheduled_at,sm.done_at,sm.source_line_id AS purchase_order_line_id,sm.return_of_move_id,parent.reference AS return_of_reference,sm.return_reason FROM stock_moves sm JOIN products p ON p.id=sm.product_id LEFT JOIN stock_moves parent ON parent.id=sm.return_of_move_id AND parent.company_id=sm.company_id WHERE sm.origin_model=\'purchase_order\' AND sm.origin_record_id=:order_id ORDER BY sm.id');$receipts->execute(['order_id'=>$id]);$order['receipts']=$receipts->fetchAll();
        $bills=$this->pdo->prepare('SELECT vb.id,vb.name,vb.vendor_reference,vb.bill_date,vb.due_date,vb.state,vb.payment_state,vb.total_amount,vb.amount_paid,vb.amount_residual,vb.accounting_move_id FROM vendor_bills vb WHERE vb.purchase_order_id=:order_id ORDER BY vb.bill_date DESC,vb.id DESC');$bills->execute(['order_id'=>$id]);$order['bills']=$bills->fetchAll();
        $order['approval']=(new \Erp\Modules\Settings\ApprovalRepository($this->pdo))->approvalForDocument('purchase_order',$id,$user,$auth);
        return $order;
    }

    public function saveDraft(?int $id,array $input,UserContext $user,Authorization $auth,int $actorId,string $ip): array
    {
        $allowed=['company_id','partner_contact_id','contract_id','buyer_user_id','warehouse_id','payment_terms_id','currency_code','order_date','order_deadline','expected_arrival','arrival_confirmation','vendor_reference','bill_control_policy','three_way_match','note','lines'];$unknown=array_diff(array_keys($input),$allowed);if($unknown)throw new InvalidArgumentException('Unsupported Purchase fields: '.implode(', ',$unknown));
        $existing=$id===null?null:$this->find($id,$user,$auth);if($id!==null&&(!$existing||$existing['state']!=='draft'))throw new InvalidArgumentException('Only a draft RFQ in an allowed company can be edited.');if($existing&&($existing['approval']['status']??null)==='pending')throw new InvalidArgumentException('This RFQ is locked while its approval layers are pending.');
        $companyId=$existing?(int)$existing['company_id']:$this->company($user,$auth,$input['company_id']??null);if(isset($input['company_id'])&&$this->positiveId($input['company_id'],'Company')!==$companyId)throw new InvalidArgumentException('An RFQ cannot be moved to another company.');
        $vendorId=$this->positiveId($input['partner_contact_id']??$existing['partner_contact_id']??null,'Supplier');$vendor=$this->supplier($vendorId,$companyId);
        $contractId=$this->nullableId($input['contract_id']??$existing['contract_id']??null,'Supplier Contract');if($contractId!==null){if(!$auth->allowsForCompany('contracts.read',$companyId))throw new \Erp\Core\Security\AccessDeniedException('Supplier Contract access is required to link a Contract.');$contracts=new \Erp\Modules\Contracts\ContractRepository($this->pdo);$active=$contracts->compatibleForOrder($companyId,$vendorId,'supplier');$kept=$existing&&(int)($existing['contract_id']??0)===$contractId&&$contracts->matchesOrder($contractId,$companyId,$vendorId,'supplier');if((!$active||(int)$active['id']!==$contractId)&&!$kept)throw new InvalidArgumentException('Select an active Supplier Contract for this company and supplier.');}
        $buyerId=$this->nullableId($input['buyer_user_id']??$existing['buyer_user_id']??$vendor['buyer_user_id']??null,'Buyer');if($buyerId!==null)$this->assertCompanyUser($buyerId,$companyId);
        $warehouseId=$this->nullableId($input['warehouse_id']??$existing['warehouse_id']??null,'Warehouse');if($warehouseId!==null)$this->warehouse($warehouseId,$companyId);
        $termsId=$this->nullableId($input['payment_terms_id']??$existing['payment_terms_id']??$vendor['supplier_payment_terms_id']??null,'Payment Terms');if($termsId!==null)$this->paymentTerms($termsId,$companyId);
        $currency=(string)($input['currency_code']??$existing['currency_code']??$this->companyCurrency($companyId));if($currency!==$this->companyCurrency($companyId))throw new InvalidArgumentException('Purchase currency must match the company currency until currency exchange rates are configured.');
        $orderDate=$this->date($input['order_date']??$existing['order_date']??gmdate('Y-m-d'),'Order Date');$deadline=$this->nullableDate($input['order_deadline']??$existing['order_deadline']??null,'Order Deadline');$arrival=$this->nullableDate($input['expected_arrival']??$existing['expected_arrival']??null,'Expected Arrival');
        $reference=$this->text($input['vendor_reference']??$existing['vendor_reference']??null,'Vendor Reference',190);$policy=(string)($input['bill_control_policy']??$existing['bill_control_policy']??'ordered');if(!in_array($policy,['ordered','received'],true))throw new InvalidArgumentException('Bill Control Policy must use ordered or received quantities.');
        $arrivalConfirmation=$this->boolean($input['arrival_confirmation']??$existing['arrival_confirmation']??false,'Arrival Confirmation');$match=$this->boolean($input['three_way_match']??$existing['three_way_match']??false,'Three-way Match');$note=$this->text($input['note']??$existing['note']??null,'Internal Note',10000);
        $rawLines=$input['lines']??($existing['lines']??[]);$lines=$this->prepareLines(is_array($rawLines)?$rawLines:[],$companyId);if(!$lines)throw new InvalidArgumentException('Add at least one product line to the RFQ.');
        $totals=['untaxed'=>'0.000000','tax'=>'0.000000','total'=>'0.000000'];foreach($lines as $line){$totals['untaxed']=$this->add($totals['untaxed'],$line['subtotal']);$totals['tax']=$this->add($totals['tax'],$line['tax_amount']);$totals['total']=$this->add($totals['total'],$line['total']);}
        $this->pdo->beginTransaction();
        try{
            if($id===null){$name=$this->nextRfqNumber($companyId,(int)substr($orderDate,0,4));$this->pdo->prepare("INSERT INTO purchase_orders (company_id,name,partner_contact_id,contract_id,buyer_user_id,warehouse_id,payment_terms_id,currency_code,order_date,order_deadline,expected_arrival,arrival_confirmation,vendor_reference,bill_control_policy,three_way_match,state,note,untaxed_amount,tax_amount,total_amount,created_by,updated_by) VALUES (:company,:name,:vendor,:contract,:buyer,:warehouse,:terms,:currency,:date,:deadline,:arrival,:arrival_confirmation,:reference,:policy,:match,'draft',:note,:untaxed,:tax,:total,:creator,:updater)")->execute(['company'=>$companyId,'name'=>$name,'vendor'=>$vendorId,'contract'=>$contractId,'buyer'=>$buyerId,'warehouse'=>$warehouseId,'terms'=>$termsId,'currency'=>$currency,'date'=>$orderDate,'deadline'=>$deadline,'arrival'=>$arrival,'arrival_confirmation'=>$arrivalConfirmation?1:0,'reference'=>$reference,'policy'=>$policy,'match'=>$match?1:0,'note'=>$note,'untaxed'=>$totals['untaxed'],'tax'=>$totals['tax'],'total'=>$totals['total'],'creator'=>$actorId,'updater'=>$actorId]);$id=(int)$this->pdo->lastInsertId();}
            else{
                $lock=$this->pdo->prepare('SELECT state,company_id FROM purchase_orders WHERE id=:id FOR UPDATE');$lock->execute(['id'=>$id]);$current=$lock->fetch();
                if(!$current||(int)$current['company_id']!==$companyId||$current['state']!=='draft')throw new InvalidArgumentException('This RFQ changed while it was being edited. Reload and try again.');
                $lockedOrder=$this->find((int)$id,$user,$auth);
                if(!$lockedOrder||$lockedOrder['state']!=='draft')throw new InvalidArgumentException('This RFQ changed while it was being edited. Reload and try again.');
                if(\Erp\Modules\Settings\ApprovalRepository::fingerprint($lockedOrder)!==\Erp\Modules\Settings\ApprovalRepository::fingerprint($existing))throw new InvalidArgumentException('This RFQ was edited by another user. Reload it before saving your changes.');
                if(($lockedOrder['approval']['status']??null)==='pending')throw new InvalidArgumentException('This RFQ is locked while its approval layers are pending.');
                $existing=$lockedOrder;
                $this->pdo->prepare('UPDATE purchase_orders SET partner_contact_id=:vendor,contract_id=:contract,buyer_user_id=:buyer,warehouse_id=:warehouse,payment_terms_id=:terms,currency_code=:currency,order_date=:date,order_deadline=:deadline,expected_arrival=:arrival,arrival_confirmation=:arrival_confirmation,vendor_reference=:reference,bill_control_policy=:policy,three_way_match=:match,note=:note,untaxed_amount=:untaxed,tax_amount=:tax,total_amount=:total,updated_by=:actor WHERE id=:id AND company_id=:company AND state=\'draft\'')->execute(['vendor'=>$vendorId,'contract'=>$contractId,'buyer'=>$buyerId,'warehouse'=>$warehouseId,'terms'=>$termsId,'currency'=>$currency,'date'=>$orderDate,'deadline'=>$deadline,'arrival'=>$arrival,'arrival_confirmation'=>$arrivalConfirmation?1:0,'reference'=>$reference,'policy'=>$policy,'match'=>$match?1:0,'note'=>$note,'untaxed'=>$totals['untaxed'],'tax'=>$totals['tax'],'total'=>$totals['total'],'actor'=>$actorId,'id'=>$id,'company'=>$companyId]);
                $this->pdo->prepare('DELETE FROM purchase_order_lines WHERE order_id=:id')->execute(['id'=>$id]);
            }
            $insert=$this->pdo->prepare('INSERT INTO purchase_order_lines (order_id,sequence,product_id,uom_id,description,quantity,unit_price,discount_percent,tax_id,tax_name_snapshot,tax_rate_snapshot,tax_included_snapshot,subtotal,tax_amount,total) VALUES (:order,:sequence,:product,:uom,:description,:quantity,:price,:discount,:tax,:tax_name,:tax_rate,:tax_included,:subtotal,:tax_amount,:total)');
            foreach($lines as $line)$insert->execute(['order'=>$id,'sequence'=>$line['sequence'],'product'=>$line['product_id'],'uom'=>$line['uom_id'],'description'=>$line['description'],'quantity'=>$line['quantity'],'price'=>$line['unit_price'],'discount'=>$line['discount_percent'],'tax'=>$line['tax_id'],'tax_name'=>$line['tax_name'],'tax_rate'=>$line['tax_rate'],'tax_included'=>$line['tax_included'],'subtotal'=>$line['subtotal'],'tax_amount'=>$line['tax_amount'],'total'=>$line['total']]);
            $this->audit($companyId,$actorId,$id,'purchase_order',$existing?'purchase_rfq_updated':'purchase_rfq_created',$existing?$this->orderAudit($existing):null,['supplier_contact_id'=>$vendorId,'buyer_user_id'=>$buyerId,'warehouse_id'=>$warehouseId,'payment_terms_id'=>$termsId,'currency_code'=>$currency,'order_date'=>$orderDate,'order_deadline'=>$deadline,'expected_arrival'=>$arrival,'arrival_confirmation'=>$arrivalConfirmation,'vendor_reference'=>$reference,'bill_control_policy'=>$policy,'three_way_match'=>$match,'line_count'=>count($lines),'total_amount'=>$totals['total'],'state'=>'draft'],$ip);
            $this->pdo->commit();
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
        return $this->find((int)$id,$user,$auth)??throw new InvalidArgumentException('RFQ was saved but could not be reloaded.');
    }

    public function markSent(int $id,UserContext $user,Authorization $auth,int $actorId,string $ip): array
    {
        $order=$this->find($id,$user,$auth);if(!$order||!in_array($order['state'],['draft','sent'],true))throw new InvalidArgumentException('Only a draft or sent RFQ can be marked sent.');if(($order['approval']['status']??null)==='pending')throw new InvalidArgumentException('This RFQ cannot change status while approval layers are pending.');
        $this->pdo->beginTransaction();
        try{
            $lock=$this->pdo->prepare('SELECT state FROM purchase_orders WHERE id=:id AND company_id=:company FOR UPDATE');$lock->execute(['id'=>$id,'company'=>$order['company_id']]);$state=$lock->fetchColumn();
            $order=$this->find($id,$user,$auth);
            if(!$order||!in_array($state,['draft','sent'],true)||$order['state']!==$state)throw new InvalidArgumentException('Only a draft or sent RFQ can be marked sent.');
            if(($order['approval']['status']??null)==='pending')throw new InvalidArgumentException('This RFQ cannot change status while approval layers are pending.');
            if($state==='draft'){
                $this->pdo->prepare("UPDATE purchase_orders SET state='sent',sent_at=UTC_TIMESTAMP(),updated_by=:actor WHERE id=:id AND company_id=:company AND state='draft'")->execute(['actor'=>$actorId,'id'=>$id,'company'=>$order['company_id']]);
                $this->audit((int)$order['company_id'],$actorId,$id,'purchase_order','purchase_rfq_sent',['state'=>'draft'],['state'=>'sent'],$ip);
            }
            $this->pdo->commit();
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
        return $this->find($id,$user,$auth)??$order;
    }

    public function confirm(int $id,UserContext $user,Authorization $auth,int $actorId,string $ip): array
    {
        $order=$this->find($id,$user,$auth);if(!$order||!in_array($order['state'],['draft','sent'],true))throw new InvalidArgumentException('Only a draft or sent RFQ can be confirmed.');if(!$order['lines'])throw new InvalidArgumentException('An RFQ needs at least one product line before confirmation.');
        $goods=array_values(array_filter($order['lines'],static fn(array $line):bool=>$line['product_type']==='goods'));if($goods&&empty($order['warehouse_id']))throw new InvalidArgumentException('Choose a receiving warehouse before confirming an RFQ containing goods.');
        $this->pdo->beginTransaction();
        try{
            $lock=$this->pdo->prepare('SELECT state,name FROM purchase_orders WHERE id=:id AND company_id=:company FOR UPDATE');$lock->execute(['id'=>$id,'company'=>$order['company_id']]);$current=$lock->fetch();if(!$current||!in_array($current['state'],['draft','sent'],true))throw new InvalidArgumentException('Only a draft or sent RFQ can be confirmed.');
            $order=$this->find($id,$user,$auth);if(!$order||$order['state']!==$current['state'])throw new InvalidArgumentException('The RFQ changed while it was being confirmed. Reload and try again.');if(!$order['lines'])throw new InvalidArgumentException('An RFQ needs at least one product line before confirmation.');
            $goods=array_values(array_filter($order['lines'],static fn(array $line):bool=>$line['product_type']==='goods'));if($goods&&empty($order['warehouse_id']))throw new InvalidArgumentException('Choose a receiving warehouse before confirming an RFQ containing goods.');
            $approval=(new \Erp\Modules\Settings\ApprovalRepository($this->pdo))->requestIfRequired('purchase_order',$id,(int)$order['company_id'],(string)$order['currency_code'],(string)$order['total_amount'],\Erp\Modules\Settings\ApprovalRepository::fingerprint($order),$actorId,$ip);if($approval!==null){$this->pdo->commit();return $this->find($id,$user,$auth)??($order+['approval'=>$approval]);}
            if($goods){$source=$this->vendorLocation((int)$order['company_id']);$dest=$this->warehouseStockLocation((int)$order['warehouse_id'],(int)$order['company_id']);$insert=$this->pdo->prepare("INSERT INTO stock_moves (company_id,reference,product_id,uom_id,source_location_id,destination_location_id,demand_quantity,state,origin_model,origin_record_id,source_line_model,source_line_id,origin_reference,scheduled_at,created_by) VALUES (:company,:reference,:product,:uom,:source,:destination,:qty,'draft','purchase_order',:order_id,'purchase_order_line',:line_id,:origin,:scheduled,:actor)");$moveLine=$this->pdo->prepare('INSERT INTO stock_move_lines (move_id,lot_id,lot_code_snapshot,expiration_date_snapshot,quantity) VALUES (:move,NULL,NULL,NULL,:quantity)');$n=0;foreach($goods as $line){$n++;$insert->execute(['company'=>$order['company_id'],'reference'=>'RCV/'.$id.'/'.$n,'product'=>$line['product_id'],'uom'=>$line['uom_id'],'source'=>$source,'destination'=>$dest,'qty'=>$line['quantity'],'order_id'=>$id,'line_id'=>$line['id'],'origin'=>$order['vendor_reference']?:$current['name'],'scheduled'=>$order['expected_arrival']?($order['expected_arrival'].' 00:00:00'):null,'actor'=>$actorId]);$moveId=(int)$this->pdo->lastInsertId();$moveLine->execute(['move'=>$moveId,'quantity'=>$line['quantity']]);}}
            $name=$this->nextPoNumber((int)$order['company_id'],(int)substr($order['order_date'],0,4));$this->pdo->prepare("UPDATE purchase_orders SET name=:name,state='purchase',confirmed_at=UTC_TIMESTAMP(),updated_by=:actor WHERE id=:id")->execute(['name'=>$name,'actor'=>$actorId,'id'=>$id]);
            $this->audit((int)$order['company_id'],$actorId,$id,'purchase_order','purchase_order_confirmed',['state'=>$order['state'],'name'=>$current['name']],['state'=>'purchase','name'=>$name,'receipt_moves_created'=>count($goods)],$ip);$this->pdo->commit();
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
        return $this->find($id,$user,$auth)??throw new InvalidArgumentException('Purchase Order was confirmed but could not be reloaded.');
    }

    public function createPurchaseTax(array $input,UserContext $user,Authorization $auth,int $actorId,string $ip): array
    {
        $unknown=array_diff(array_keys($input),['company_id','name','amount','price_included','account_id']);if($unknown)throw new InvalidArgumentException('Unsupported Purchase tax fields: '.implode(', ',$unknown));$company=$this->company($user,$auth,$input['company_id']??null);$name=$this->text($input['name']??null,'Tax Name',120);if(!$name)throw new InvalidArgumentException('Tax Name is required.');$rate=$this->decimal($input['amount']??0,'Tax Rate',4);if((float)$rate>100)throw new InvalidArgumentException('Tax Rate cannot exceed 100%.');$included=$this->boolean($input['price_included']??false,'Price Included');$accountId=$this->nullableId($input['account_id']??null,'Recoverable Tax Account');if((float)$rate>0){$account=$accountId?$this->account($accountId,$company):null;if(!$account||!in_array($account['account_type'],['asset_current','asset_non_current'],true))throw new InvalidArgumentException('A non-zero purchase tax needs an active company Recoverable Tax asset account.');}
        $this->pdo->prepare('INSERT INTO purchase_taxes (company_id,name,amount,price_included,account_id) VALUES (:company,:name,:rate,:included,:account)')->execute(['company'=>$company,'name'=>$name,'rate'=>$rate,'included'=>$included?1:0,'account'=>$accountId]);$id=(int)$this->pdo->lastInsertId();$this->audit($company,$actorId,$id,'purchase_tax','purchase_tax_created',null,['name'=>$name,'amount'=>$rate,'price_included'=>$included,'account_id'=>$accountId],$ip);$q=$this->pdo->prepare('SELECT id,name,amount,price_included,account_id FROM purchase_taxes WHERE id=:id');$q->execute(['id'=>$id]);return $q->fetch()?:[];
    }

    public function createBillFromOrder(int $orderId,UserContext $user,Authorization $auth,int $actorId,string $ip): array
    {
        $this->pdo->beginTransaction();
        try{
            $q=$this->pdo->prepare('SELECT po.*,c.supplier_payment_terms_id,co.currency_code AS company_currency,cur.decimal_places,pt.due_days AS order_due_days,spt.due_days AS supplier_due_days FROM purchase_orders po JOIN contacts c ON c.id=po.partner_contact_id JOIN companies co ON co.id=po.company_id JOIN currencies cur ON cur.currency_code=po.currency_code LEFT JOIN payment_terms pt ON pt.id=po.payment_terms_id LEFT JOIN payment_terms spt ON spt.id=c.supplier_payment_terms_id WHERE po.id=:id FOR UPDATE');$q->execute(['id'=>$orderId]);$order=$q->fetch();if(!$order||!$auth->canAccessCompany((int)$order['company_id']))throw new InvalidArgumentException('Purchase Order was not found or is outside the allowed companies.');if($order['state']!=='purchase')throw new InvalidArgumentException('Only a confirmed Purchase Order can create a vendor bill.');if($order['currency_code']!==$order['company_currency'])throw new InvalidArgumentException('Vendor bills must use the company currency until exchange rates are configured.');
            $lineQ=$this->pdo->prepare('SELECT pol.*,p.product_type,(SELECT COALESCE(SUM(CASE WHEN sm.return_of_move_id IS NULL THEN sm.done_quantity ELSE 0-sm.done_quantity END),0) FROM stock_moves sm WHERE sm.source_line_model=\'purchase_order_line\' AND sm.source_line_id=pol.id AND sm.state=\'done\') AS received_qty,(SELECT COALESCE(SUM(vbl.quantity),0) FROM vendor_bill_lines vbl JOIN vendor_bills vb ON vb.id=vbl.bill_id WHERE vbl.purchase_order_line_id=pol.id AND vb.state IN (\'draft\',\'posted\')) AS billed_qty FROM purchase_order_lines pol JOIN products p ON p.id=pol.product_id WHERE pol.order_id=:order ORDER BY pol.sequence,pol.id FOR UPDATE');$lineQ->execute(['order'=>$orderId]);$orderLines=$lineQ->fetchAll();$billLines=[];$untaxed='0.000000';$tax='0.000000';$total='0.000000';
            foreach($orderLines as $line){$basis=(string)$line['quantity'];if($order['bill_control_policy']==='received'){if($line['product_type']==='service')throw new InvalidArgumentException('Received-quantity billing for Services needs a service receipt workflow; use Ordered quantities for this RFQ.');$basis=(string)$line['received_qty'];}$remaining=$this->subtract($basis,(string)$line['billed_qty']);if((float)$remaining<=0.0000001)continue;$billLines[]=['source'=>$line,'quantity'=>$remaining];$untaxed=$this->add($untaxed,$this->mul((string)$line['subtotal'],$remaining,(string)$line['quantity']));$tax=$this->add($tax,$this->mul((string)$line['tax_amount'],$remaining,(string)$line['quantity']));$total=$this->add($total,$this->mul((string)$line['total'],$remaining,(string)$line['quantity']));}
            if(!$billLines)throw new InvalidArgumentException($order['bill_control_policy']==='received'?'No unbilled received quantity is available. Validate a linked receipt first.':'All ordered quantities on this Purchase Order are already included in draft or posted vendor bills.');
            $journalQ=$this->pdo->prepare("SELECT id FROM accounting_journals WHERE company_id=:company AND active=1 AND journal_type='purchase' ORDER BY id LIMIT 1 FOR UPDATE");$journalQ->execute(['company'=>$order['company_id']]);$journal=$journalQ->fetchColumn();if(!$journal)throw new InvalidArgumentException('Create an active Purchase Journal in Accounting before creating vendor bills.');
            $date=gmdate('Y-m-d');$terms=(int)($order['payment_terms_id']?:$order['supplier_payment_terms_id']);$days=(int)($order['order_due_days']??$order['supplier_due_days']??0);$due=(new \DateTimeImmutable($date))->modify(($days>=0?'+':'').$days.' days')->format('Y-m-d');$draft='Draft/PO'.$orderId.'/'.$this->billOrdinal($orderId);
            $this->pdo->prepare("INSERT INTO vendor_bills (company_id,name,purchase_order_id,partner_contact_id,journal_id,currency_code,vendor_reference,bill_date,accounting_date,due_date,state,payment_state,untaxed_amount,tax_amount,total_amount,amount_residual,created_by,updated_by) VALUES (:company,:name,:order,:vendor,:journal,:currency,:reference,:bill_date,:accounting_date,:due,'draft','not_applicable',:untaxed,:tax,:total,0,:creator,:updater)")->execute(['company'=>$order['company_id'],'name'=>$draft,'order'=>$orderId,'vendor'=>$order['partner_contact_id'],'journal'=>$journal,'currency'=>$order['currency_code'],'reference'=>$order['vendor_reference'],'bill_date'=>$date,'accounting_date'=>$date,'due'=>$due,'untaxed'=>$untaxed,'tax'=>$tax,'total'=>$total,'creator'=>$actorId,'updater'=>$actorId]);$billId=(int)$this->pdo->lastInsertId();
            $insert=$this->pdo->prepare('INSERT INTO vendor_bill_lines (bill_id,purchase_order_line_id,sequence,product_id,uom_id,description,quantity,unit_price,discount_percent,tax_id,tax_name_snapshot,tax_rate_snapshot,tax_included_snapshot,subtotal,tax_amount,total) VALUES (:bill,:source,:sequence,:product,:uom,:description,:quantity,:price,:discount,:tax,:tax_name,:tax_rate,:tax_included,:subtotal,:tax_amount,:total)');$sequence=10;
            foreach($billLines as $item){$line=$item['source'];$fraction=(float)$item['quantity']/(float)$line['quantity'];$sub=$this->mul((string)$line['subtotal'],$item['quantity'],(string)$line['quantity']);$tx=$this->mul((string)$line['tax_amount'],$item['quantity'],(string)$line['quantity']);$lineTotal=$this->add($sub,$tx);$insert->execute(['bill'=>$billId,'source'=>$line['id'],'sequence'=>$sequence,'product'=>$line['product_id'],'uom'=>$line['uom_id'],'description'=>$line['description'],'quantity'=>$item['quantity'],'price'=>$line['unit_price'],'discount'=>$line['discount_percent'],'tax'=>$line['tax_id'],'tax_name'=>$line['tax_name_snapshot'],'tax_rate'=>$line['tax_rate_snapshot'],'tax_included'=>$line['tax_included_snapshot'],'subtotal'=>$sub,'tax_amount'=>$tx,'total'=>$lineTotal]);$sequence+=10;}
            $this->audit((int)$order['company_id'],$actorId,$billId,'vendor_bill','vendor_bill_created_from_purchase',null,['purchase_order_id'=>$orderId,'supplier_contact_id'=>$order['partner_contact_id'],'line_count'=>count($billLines),'total_amount'=>$total,'bill_control_policy'=>$order['bill_control_policy']],$ip);$this->pdo->commit();
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
        return $this->findBill($billId,$user,$auth)??throw new InvalidArgumentException('Vendor bill was created but could not be reloaded.');
    }

    public function searchBills(UserContext $user,Authorization $auth,array $filters): array
    {
        $company=$this->company($user,$auth,$filters['company_id']??null);$where=['vb.company_id=:company'];$params=['company'=>$company];$state=(string)($filters['state']??'all');if($state!=='all'){if(!in_array($state,['draft','posted','cancelled'],true))throw new InvalidArgumentException('Select a valid vendor bill state.');$where[]='vb.state=:state';$params['state']=$state;}if(($filters['partner_contact_id']??'')!==''){$where[]='vb.partner_contact_id=:partner';$params['partner']=$this->positiveId($filters['partner_contact_id'],'Supplier Contact');}$text=trim((string)($filters['q']??''));if($text!==''){if(mb_strlen($text)>190)throw new InvalidArgumentException('Vendor bill search is too long.');$like='%'.str_replace(['!','%','_'],['!!','!%','!_'],$text).'%';$where[]='(vb.name LIKE :name_q OR vb.vendor_reference LIKE :ref_q OR c.name LIKE :vendor_q OR po.name LIKE :po_q)';$params+=['name_q'=>$like,'ref_q'=>$like,'vendor_q'=>$like,'po_q'=>$like];}$clause=implode(' AND ',$where);$count=$this->pdo->prepare('SELECT COUNT(*) FROM vendor_bills vb JOIN contacts c ON c.id=vb.partner_contact_id JOIN purchase_orders po ON po.id=vb.purchase_order_id WHERE '.$clause);$count->execute($params);$limit=max(1,min(100,(int)($filters['limit']??50)));$offset=max(0,min(1000000,(int)($filters['offset']??0)));$q=$this->pdo->prepare('SELECT vb.id,vb.company_id,vb.name,vb.purchase_order_id,po.name AS purchase_order_name,vb.partner_contact_id,c.name AS supplier_name,vb.vendor_reference,vb.bill_date,vb.due_date,vb.state,vb.payment_state,vb.total_amount,vb.amount_paid,vb.amount_credited,vb.amount_residual,vb.currency_code,vb.accounting_move_id,(SELECT COALESCE(SUM(vcn.amount),0) FROM vendor_credit_notes vcn WHERE vcn.company_id=vb.company_id AND vcn.vendor_bill_id=vb.id AND vcn.state=\'posted\') AS supplier_credit_note_amount,(SELECT COALESCE(SUM(vcn.amount_refunded),0) FROM vendor_credit_notes vcn WHERE vcn.company_id=vb.company_id AND vcn.vendor_bill_id=vb.id AND vcn.state=\'posted\') AS supplier_refunded_amount,(SELECT COALESCE(SUM(vcn.amount_applied),0) FROM vendor_credit_notes vcn WHERE vcn.company_id=vb.company_id AND vcn.vendor_bill_id=vb.id AND vcn.state=\'posted\') AS supplier_credit_applied_amount,(SELECT COALESCE(SUM(vcn.amount_residual),0) FROM vendor_credit_notes vcn WHERE vcn.company_id=vb.company_id AND vcn.vendor_bill_id=vb.id AND vcn.state=\'posted\') AS supplier_credit_open_amount FROM vendor_bills vb JOIN contacts c ON c.id=vb.partner_contact_id JOIN purchase_orders po ON po.id=vb.purchase_order_id WHERE '.$clause.' ORDER BY vb.bill_date DESC,vb.id DESC LIMIT :limit OFFSET :offset');foreach($params as $key=>$value)$q->bindValue(':'.$key,$value,is_int($value)?PDO::PARAM_INT:PDO::PARAM_STR);$q->bindValue(':limit',$limit,PDO::PARAM_INT);$q->bindValue(':offset',$offset,PDO::PARAM_INT);$q->execute();return ['records'=>$q->fetchAll(),'total'=>(int)$count->fetchColumn(),'company_id'=>$company,'limit'=>$limit,'offset'=>$offset];
    }

    public function findBill(int $id,UserContext $user,Authorization $auth): ?array
    {
        $q=$this->pdo->prepare('SELECT vb.*,po.name AS purchase_order_name,po.three_way_match,po.bill_control_policy,c.name AS supplier_name,c.email AS supplier_email,c.payable_account_id,j.name AS journal_name,am.name AS accounting_move_name,am.state AS accounting_move_state FROM vendor_bills vb JOIN purchase_orders po ON po.id=vb.purchase_order_id JOIN contacts c ON c.id=vb.partner_contact_id JOIN accounting_journals j ON j.id=vb.journal_id LEFT JOIN accounting_moves am ON am.id=vb.accounting_move_id WHERE vb.id=:id');$q->execute(['id'=>$id]);$bill=$q->fetch();if(!$bill||!$auth->canAccessCompany((int)$bill['company_id']))return null;
        $canReadAccounting=$auth->allowsForCompany('accounting.read',(int)$bill['company_id']);if(!$canReadAccounting){$bill['accounting_move_name']=null;$bill['accounting_move_state']=null;}
        $lines=$this->pdo->prepare('SELECT vbl.*,p.name AS product_name,p.product_type,p.purchase_account_id,pt.account_id AS tax_account_id,u.name AS uom_name FROM vendor_bill_lines vbl JOIN products p ON p.id=vbl.product_id LEFT JOIN purchase_taxes pt ON pt.id=vbl.tax_id JOIN units_of_measure u ON u.id=vbl.uom_id WHERE vbl.bill_id=:bill ORDER BY vbl.sequence,vbl.id');$lines->execute(['bill'=>$id]);$bill['lines']=$lines->fetchAll();
        $moveLines=$this->pdo->prepare('SELECT ml.id,ml.sequence,ml.account_id,a.code AS account_code,a.name AS account_name,ml.contact_id,ml.label,ml.debit,ml.credit,ml.currency_code,ml.amount_currency FROM accounting_move_lines ml JOIN accounting_accounts a ON a.id=ml.account_id WHERE ml.move_id=:move ORDER BY ml.sequence,ml.id');$moveLines->execute(['move'=>$bill['accounting_move_id']??0]);$bill['journal_items']=$canReadAccounting?$moveLines->fetchAll():[];
        $payments=$this->pdo->prepare('SELECT vp.id,vp.name,vp.payment_date,vp.amount,vp.reference,vp.state,vp.accounting_move_id,am.name AS accounting_move_name,am.state AS accounting_move_state,bsm.reference AS bank_reference,bsm.transaction_date AS bank_transaction_date,bsm.accounting_move_id AS bank_move_id,bank_am.name AS bank_move_name,bank_am.state AS bank_move_state FROM vendor_payments vp LEFT JOIN accounting_moves am ON am.id=vp.accounting_move_id LEFT JOIN vendor_bank_statement_matches bsm ON bsm.payment_id=vp.id LEFT JOIN accounting_moves bank_am ON bank_am.id=bsm.accounting_move_id WHERE vp.vendor_bill_id=:bill ORDER BY vp.payment_date DESC,vp.id DESC');$payments->execute(['bill'=>$id]);$bill['payments']=$payments->fetchAll();if(!$canReadAccounting){foreach($bill['payments'] as &$payment){foreach(['accounting_move_name','accounting_move_state','bank_move_name','bank_move_state'] as $field)$payment[$field]=null;}unset($payment);}
        $credits=$this->pdo->prepare('SELECT vc.id,vc.name,vc.credit_date,vc.reason,vc.amount,vc.amount_refunded,vc.amount_applied,vc.amount_residual,vc.state,vc.accounting_move_id,am.name AS accounting_move_name,am.state AS accounting_move_state FROM vendor_credit_notes vc LEFT JOIN accounting_moves am ON am.id=vc.accounting_move_id WHERE vc.company_id=:company AND vc.vendor_bill_id=:bill ORDER BY vc.credit_date DESC,vc.id DESC');$credits->execute(['company'=>$bill['company_id'],'bill'=>$id]);$bill['credit_notes']=$credits->fetchAll();$refundQuery=$this->pdo->prepare('SELECT r.id,r.name,r.refund_date,r.amount,r.reference,r.state,r.accounting_move_id,ram.name AS accounting_move_name,ram.state AS accounting_move_state,m.reference AS bank_reference,m.transaction_date AS bank_transaction_date,m.accounting_move_id AS bank_move_id,bam.name AS bank_move_name,bam.state AS bank_move_state FROM vendor_credit_note_refunds r LEFT JOIN accounting_moves ram ON ram.id=r.accounting_move_id LEFT JOIN vendor_credit_note_refund_matches m ON m.refund_id=r.id LEFT JOIN accounting_moves bam ON bam.id=m.accounting_move_id WHERE r.company_id=:company AND r.credit_note_id=:credit_note ORDER BY r.refund_date DESC,r.id DESC');foreach($bill['credit_notes'] as &$credit){$credit['id']=(int)$credit['id'];$refundQuery->execute(['company'=>$bill['company_id'],'credit_note'=>$credit['id']]);$credit['refunds']=$refundQuery->fetchAll();if(!$canReadAccounting){$credit['accounting_move_name']=null;$credit['accounting_move_state']=null;foreach($credit['refunds'] as &$refund){foreach(['accounting_move_name','accounting_move_state','bank_move_name','bank_move_state'] as $field)$refund[$field]=null;}unset($refund);}}        $applications=$this->pdo->prepare("SELECT a.id,a.credit_note_id,cn.name AS credit_note_name,cn.vendor_bill_id AS source_bill_id,source.name AS source_bill_name,a.vendor_bill_id AS target_bill_id,target.name AS target_bill_name,a.amount,a.applied_at FROM vendor_credit_note_applications a JOIN vendor_credit_notes cn ON cn.id=a.credit_note_id AND cn.company_id=a.company_id JOIN vendor_bills source ON source.id=cn.vendor_bill_id AND source.company_id=cn.company_id JOIN vendor_bills target ON target.id=a.vendor_bill_id AND target.company_id=a.company_id WHERE a.company_id=:company AND (a.vendor_bill_id=:target_bill OR cn.vendor_bill_id=:source_bill) ORDER BY a.applied_at DESC,a.id DESC");$applications->execute(['company'=>$bill['company_id'],'target_bill'=>$id,'source_bill'=>$id]);$bill['credit_applications']=$applications->fetchAll();unset($credit);return $bill;
    }

    public function createFullVendorCreditNote(int $billId,array $input,UserContext $user,Authorization $auth,int $actorId,string $ip):array
    {
        $unknown=array_diff(array_keys($input),['credit_date','reason']);if($unknown)throw new InvalidArgumentException('Unsupported supplier credit note fields: '.implode(', ',$unknown));
        $date=$this->date($input['credit_date']??null,'Credit Note Date');$reason=trim((string)($input['reason']??''));if($reason===''||mb_strlen($reason)>190)throw new InvalidArgumentException('Credit Note Reason is required and must be 190 characters or fewer.');
        $bill=$this->findBill($billId,$user,$auth);if(!$bill||$bill['state']!=='posted')throw new InvalidArgumentException('A supplier credit note requires a posted vendor bill.');
        $this->pdo->beginTransaction();
        try{
            $lock=$this->pdo->prepare("SELECT vb.*,co.currency_code AS company_currency,cur.decimal_places FROM vendor_bills vb JOIN companies co ON co.id=vb.company_id JOIN currencies cur ON cur.currency_code=vb.currency_code WHERE vb.id=:bill AND vb.company_id=:company AND vb.state='posted' FOR UPDATE");$lock->execute(['bill'=>$billId,'company'=>$bill['company_id']]);$current=$lock->fetch();if(!$current)throw new InvalidArgumentException('The source vendor bill is no longer posted. Reload and try again.');
            $existing=$this->pdo->prepare("SELECT name FROM vendor_credit_notes WHERE company_id=:company AND vendor_bill_id=:bill AND state IN ('draft','posted') ORDER BY id LIMIT 1 FOR UPDATE");$existing->execute(['company'=>$current['company_id'],'bill'=>$billId]);$existingName=$existing->fetchColumn();if($existingName!==false)throw new InvalidArgumentException('A full supplier credit note already exists for this bill: '.$existingName.'.');
            if($current['currency_code']!==$current['company_currency'])throw new InvalidArgumentException('Supplier credit notes must use the company currency until exchange rates are configured.');
            if($this->minor((string)$current['total_amount'],(int)$current['decimal_places'])<1)throw new InvalidArgumentException('A zero value bill cannot be credited.');
            $name=$this->nextVendorCreditNoteNumber((int)$current['company_id'],(int)substr($date,0,4));
            $this->pdo->prepare("INSERT INTO vendor_credit_notes (company_id,name,vendor_bill_id,partner_contact_id,journal_id,currency_code,credit_date,reason,amount,state,created_by) VALUES (:company,:name,:bill,:partner,:journal,:currency,:date,:reason,:amount,'draft',:actor)")->execute(['company'=>$current['company_id'],'name'=>$name,'bill'=>$billId,'partner'=>$current['partner_contact_id'],'journal'=>$current['journal_id'],'currency'=>$current['currency_code'],'date'=>$date,'reason'=>$reason,'amount'=>$current['total_amount'],'actor'=>$actorId]);$creditId=(int)$this->pdo->lastInsertId();
            $this->audit((int)$current['company_id'],$actorId,$creditId,'vendor_credit_note','vendor_credit_note_created',null,['name'=>$name,'vendor_bill_id'=>$billId,'amount'=>$current['total_amount'],'credit_date'=>$date,'reason'=>$reason,'state'=>'draft','scope'=>'full_bill_reversal'],$ip);$this->pdo->commit();
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
        return $this->findBill($billId,$user,$auth)??throw new InvalidArgumentException('Supplier credit note was created but the source bill could not be reloaded.');
    }

    public function postVendorCreditNote(int $id,UserContext $user,Authorization $auth,int $actorId,string $ip):array
    {
        $lookup=$this->pdo->prepare('SELECT vendor_bill_id,company_id FROM vendor_credit_notes WHERE id=:id');$lookup->execute(['id'=>$id]);$target=$lookup->fetch();if(!$target||!$auth->canAccessCompany((int)$target['company_id']))throw new InvalidArgumentException('Supplier credit note was not found.');if(!$auth->allowsForCompany('accounting.post',(int)$target['company_id']))throw new AccessDeniedException('You need Accounting Posting access for this company.');
        $this->pdo->beginTransaction();
        try{
            $q=$this->pdo->prepare("SELECT vc.*,vb.name AS bill_name,vb.state AS bill_state,vb.accounting_move_id AS source_move_id,vb.total_amount AS bill_total,vb.currency_code AS bill_currency,co.currency_code AS company_currency,cur.decimal_places FROM vendor_credit_notes vc JOIN vendor_bills vb ON vb.id=vc.vendor_bill_id AND vb.company_id=vc.company_id JOIN companies co ON co.id=vc.company_id JOIN currencies cur ON cur.currency_code=vc.currency_code WHERE vc.id=:id AND vc.company_id=:company FOR UPDATE");$q->execute(['id'=>$id,'company'=>$target['company_id']]);$credit=$q->fetch();if(!$credit||$credit['state']!=='draft'||$credit['bill_state']!=='posted')throw new InvalidArgumentException('Only a draft supplier credit note from a posted bill can be posted.');
            if($credit['currency_code']!==$credit['company_currency']||$credit['currency_code']!==$credit['bill_currency'])throw new InvalidArgumentException('Supplier credit note currency must match the company and source bill.');
            \Erp\Modules\Accounting\AccountingDateGuard::lockAndAssertOpen($this->pdo,(int)$credit['company_id'],(string)$credit['credit_date']);
            $source=$this->pdo->prepare("SELECT am.id,am.journal_id,am.currency_code,am.state,am.total_debit,am.total_credit FROM accounting_moves am WHERE am.id=:move AND am.company_id=:company AND am.reference_model='vendor_bill' AND am.state='posted' FOR UPDATE");$source->execute(['move'=>$credit['source_move_id'],'company'=>$credit['company_id']]);$sourceMove=$source->fetch();if(!$sourceMove||$sourceMove['currency_code']!==$credit['currency_code'])throw new InvalidArgumentException('The source bill must have a posted Accounting entry in the same currency.');
