            $places=(int)$note['decimal_places'];$billPlaces=(int)$bill['decimal_places'];if($places!==$billPlaces)throw new InvalidArgumentException('The bill and credit note currency precision do not match.');
            $noteResidual=$this->minor((string)$note['amount_residual'],$places);$billResidual=$this->minor((string)$bill['amount_residual'],$places);$amountMinor=$this->minor((string)($input['amount']??''),$places);
