            $noteLineQuery=$this->pdo->prepare("SELECT ml.id,ml.account_id,ml.contact_id,ml.currency_code FROM accounting_move_lines ml JOIN accounting_moves am ON am.id=ml.move_id AND am.company_id=:company AND am.state='posted' WHERE ml.move_id=:move AND ml.account_id=:account AND ml.contact_id=:contact AND ml.debit>0 AND ml.credit=0 AND ml.currency_code=:currency ORDER BY ml.id LIMIT 1 FOR UPDATE");
            $noteLineQuery->execute(['company'=>$note['company_id'],'move'=>$note['accounting_move_id'],'account'=>$payableId,'contact'=>$note['supplier_id'],'currency'=>$note['currency_code']]);$noteLine=$noteLineQuery->fetch();
            $billLineQuery=$this->pdo->prepare("SELECT ml.id,ml.account_id,ml.contact_id,ml.currency_code FROM accounting_move_lines ml JOIN accounting_moves am ON am.id=ml.move_id AND am.company_id=:company AND am.state='posted' WHERE ml.move_id=:move AND ml.account_id=:account AND ml.contact_id=:contact AND ml.credit>0 AND ml.debit=0 AND ml.currency_code=:currency ORDER BY ml.id LIMIT 1 FOR UPDATE");
