            $this->audit((int)$note['company_id'],$actorId,$creditNoteId,'vendor_credit_note','supplier_credit_applied',['amount_applied'=>$note['amount_applied'],'amount_residual'=>$note['amount_residual']],['amount_applied'=>$newNoteApplied,'amount_residual'=>$newNoteResidual,'application_id'=>$applicationId],$ip);
            $this->audit((int)$note['company_id'],$actorId,$billId,'vendor_bill','supplier_credit_applied',['amount_credited'=>$bill['amount_credited'],'amount_residual'=>$bill['amount_residual'],'payment_state'=>$bill['payment_state']],['amount_credited'=>$newBillCredited,'amount_residual'=>$newBillResidual,'payment_state'=>$paymentState,'application_id'=>$applicationId],$ip);
            $this->pdo->commit();
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
