            $name=$this->nextVendorPaymentNumber((int)$current['company_id'],(int)substr($date,0,4));$amount=$this->decimalFromMinor($amountMinor,$places);$this->pdo->prepare("INSERT INTO vendor_payments (company_id,name,vendor_bill_id,partner_contact_id,journal_id,currency_code,payment_date,amount,reference,state,created_by) VALUES (:company,:name,:bill,:vendor,:journal,:currency,:date,:amount,:reference,'in_payment',:actor)")->execute(['company'=>$current['company_id'],'name'=>$name,'bill'=>$billId,'vendor'=>$current['partner_contact_id'],'journal'=>$journalId,'currency'=>$current['currency_code'],'date'=>$date,'amount'=>$amount,'reference'=>$reference,'actor'=>$actorId]);$paymentId=(int)$this->pdo->lastInsertId();$this->pdo->prepare("INSERT INTO accounting_moves (company_id,name,journal_id,move_type,reference_model,reference_id,reference,accounting_date,currency_code,state,total_debit,total_credit,created_by) VALUES (:company,:name,:journal,'vendor_payment','vendor_payment',:payment,:reference,:date,:currency,'draft',:debit,:credit,:actor)")->execute(['company'=>$current['company_id'],'name'=>$name,'journal'=>$journalId,'payment'=>$paymentId,'reference'=>$name.' · '.$current['name'],'date'=>$date,'currency'=>$current['currency_code'],'debit'=>$amount,'credit'=>$amount,'actor'=>$actorId]);$moveId=(int)$this->pdo->lastInsertId();$insert=$this->pdo->prepare('INSERT INTO accounting_move_lines (move_id,sequence,account_id,contact_id,label,debit,credit,currency_code,amount_currency) VALUES (:move,:sequence,:account,:contact,:label,:debit,:credit,:currency,:amount)');$insert->execute(['move'=>$moveId,'sequence'=>10,'account'=>$payableId,'contact'=>$current['partner_contact_id'],'label'=>'Supplier Payable · '.$current['name'],'debit'=>$amount,'credit'=>'0','currency'=>$current['currency_code'],'amount'=>$amount]);$paymentLine=(int)$this->pdo->lastInsertId();$insert->execute(['move'=>$moveId,'sequence'=>20,'account'=>$journal['outstanding_payments_account_id'],'contact'=>