    public function reconcileVendorPayment(int $paymentId,array $input,UserContext $user,Authorization $auth,int $actorId,string $ip): array
    {
        $unknown=array_diff(array_keys($input),['reference','transaction_date','amount','statement_line_id']);
        if($unknown)throw new InvalidArgumentException('Unsupported bank match fields: '.implode(', ',$unknown));
        $statementLineId=null;
        if(array_key_exists('statement_line_id',$input)){$statementLineId=filter_var($input['statement_line_id'],FILTER_VALIDATE_INT);if($statementLineId===false||$statementLineId<1)throw new InvalidArgumentException('Bank statement line ID must be a positive integer.');}
        $reference=$statementLineId===null?($this->text($input['reference']??null,'Bank Reference',190)??''):'';
        if($statementLineId===null&&$reference==='')throw new InvalidArgumentException('Bank Reference is required.');
        $date=$statementLineId===null?$this->date($input['transaction_date']??null,'Transaction Date'):'';
        $q=$this->pdo->prepare('SELECT vp.id,vp.company_id,vp.vendor_bill_id,vp.partner_contact_id,vp.name,vp.journal_id,vp.currency_code,vp.amount,vp.state,vb.name AS bill_name,vb.amount_residual,vb.amount_paid,vb.amount_credited,vb.total_amount,vb.payment_state,j.default_account_id,j.outstanding_payments_account_id,cur.decimal_places FROM vendor_payments vp JOIN vendor_bills vb ON vb.id=vp.vendor_bill_id JOIN accounting_journals j ON j.id=vp.journal_id JOIN currencies cur ON cur.currency_code=vp.currency_code WHERE vp.id=:id');
        $q->execute(['id'=>$paymentId]);$payment=$q->fetch();
        if(!$payment||!$auth->canAccessCompany((int)$payment['company_id']))throw new InvalidArgumentException('Vendor payment was not found.');
        if(!$auth->allowsForCompany('accounting.reconcile',(int)$payment['company_id'])||!$auth->allowsForCompany('accounting.post',(int)$payment['company_id']))throw new AccessDeniedException('You need Reconciliation and Posting access for this company.');
        $this->pdo->beginTransaction();
        try{
            $lock=$this->pdo->prepare('SELECT state FROM vendor_payments WHERE id=:id AND company_id=:company FOR UPDATE');$lock->execute(['id'=>$paymentId,'company'=>$payment['company_id']]);
            if($lock->fetchColumn()!=='in_payment')throw new InvalidArgumentException('Only an unreconciled vendor payment can be matched.');
            $places=(int)$payment['decimal_places'];
            if($statementLineId!==null){
                $lineQuery=$this->pdo->prepare('SELECT l.transaction_date,l.reference,l.amount,l.currency_code,s.state,s.company_id,s.journal_id FROM bank_statement_lines l JOIN bank_statements s ON s.id=l.statement_id WHERE l.id=:line FOR UPDATE');
                $lineQuery->execute(['line'=>$statementLineId]);$line=$lineQuery->fetch();
                if(!$line||(int)$line['company_id']!==(int)$payment['company_id']||(int)$line['journal_id']!==(int)$payment['journal_id']||$line['state']!=='imported'||$line['currency_code']!==$payment['currency_code'])throw new InvalidArgumentException('Imported statement line must be open and use the same company, journal, and currency as this payment.');
                if(!str_starts_with((string)$line['amount'],'-'))throw new InvalidArgumentException('A vendor payment can only match a negative bank statement amount.');
                $already=$this->pdo->prepare('SELECT (EXISTS(SELECT 1 FROM bank_statement_matches WHERE statement_line_id=:customer_line) OR EXISTS(SELECT 1 FROM customer_credit_note_refund_matches WHERE statement_line_id=:customer_refund_line) OR EXISTS(SELECT 1 FROM vendor_bank_statement_matches WHERE statement_line_id=:vendor_line) OR EXISTS(SELECT 1 FROM vendor_credit_note_refund_matches WHERE statement_line_id=:vendor_refund_line) OR EXISTS(SELECT 1 FROM bank_statement_account_matches WHERE statement_line_id=:account_line))');
                $already->execute(['customer_line'=>$statementLineId,'customer_refund_line'=>$statementLineId,'vendor_line'=>$statementLineId,'vendor_refund_line'=>$statementLineId,'account_line'=>$statementLineId]);if((bool)$already->fetchColumn())throw new InvalidArgumentException('This bank statement line is already reconciled.');
                $date=(string)$line['transaction_date'];$reference=trim((string)$line['reference']);$lineAmount=substr((string)$line['amount'],1);$amountMinor=$this->minor($lineAmount,$places);
            }else{$amountMinor=$this->minor((string)($input['amount']??''),$places);}
            if($amountMinor<1||$amountMinor!==$this->minor((string)$payment['amount'],$places))throw new InvalidArgumentException('The statement amount must exactly match the registered vendor payment.');
            \Erp\Modules\Accounting\AccountingDateGuard::lockAndAssertOpen($this->pdo,(int)$payment['company_id'],$date);
            $matches=$this->pdo->prepare('SELECT id FROM vendor_bank_statement_matches WHERE payment_id=:payment');$matches->execute(['payment'=>$paymentId]);if($matches->fetchColumn())throw new InvalidArgumentException('This vendor payment is already matched to a bank statement line.');
            $bank=$this->account((int)$payment['default_account_id'],(int)$payment['company_id']);$outstanding=$this->account((int)$payment['outstanding_payments_account_id'],(int)$payment['company_id']);
            if(!$bank||!in_array($bank['account_type'],['asset_cash','asset_current'],true)||!$outstanding||!in_array($outstanding['account_type'],['asset_cash','asset_current'],true))throw new InvalidArgumentException('Bank/Cash and Outstanding Payments accounts must be active.');
            $amount=$this->decimalFromMinor($amountMinor,$places);
            $this->pdo->prepare('INSERT INTO vendor_bank_statement_matches (company_id,journal_id,payment_id,statement_line_id,reference,transaction_date,amount,currency_code,created_by,matched_at) VALUES (:company,:journal,:payment,:statement_line,:reference,:date,:amount,:currency,:actor,UTC_TIMESTAMP())')->execute(['company'=>$payment['company_id'],'journal'=>$payment['journal_id'],'payment'=>$paymentId,'statement_line'=>$statementLineId,'reference'=>$reference,'date'=>$date,'amount'=>$amount,'currency'=>$payment['currency_code'],'actor'=>$actorId]);
            $matchId=(int)$this->pdo->lastInsertId();$name=sprintf('VBK%04d-%06d',(int)substr($date,0,4),$matchId);
            $this->pdo->prepare("INSERT INTO accounting_moves (company_id,name,journal_id,move_type,reference_model,reference_id,reference,accounting_date,currency_code,state,total_debit,total_credit,created_by) VALUES (:company,:name,:journal,'vendor_bank_reconciliation','vendor_bank_statement_match',:match_id,:reference,:date,:currency,'draft',:debit,:credit,:actor)")->execute(['company'=>$payment['company_id'],'name'=>$name,'journal'=>$payment['journal_id'],'match_id'=>$matchId,'reference'=>$reference.' · '.$payment['name'],'date'=>$date,'currency'=>$payment['currency_code'],'debit'=>$amount,'credit'=>$amount,'actor'=>$actorId]);
            $moveId=(int)$this->pdo->lastInsertId();$insert=$this->pdo->prepare('INSERT INTO accounting_move_lines (move_id,sequence,account_id,contact_id,label,debit,credit,currency_code,amount_currency) VALUES (:move,:sequence,:account,:contact,:label,:debit,:credit,:currency,:amount)');
            $insert->execute(['move'=>$moveId,'sequence'=>10,'account'=>$payment['outstanding_payments_account_id'],'contact'=>$payment['partner_contact_id'],'label'=>'Clear Outstanding Payments · '.$payment['name'],'debit'=>$amount,'credit'=>'0','currency'=>$payment['currency_code'],'amount'=>$amount]);
            $insert->execute(['move'=>$moveId,'sequence'=>20,'account'=>$payment['default_account_id'],'contact'=>$payment['partner_contact_id'],'label'=>'Bank Statement · '.$reference,'debit'=>'0','credit'=>$amount,'currency'=>$payment['currency_code'],'amount'=>'-'.$amount]);
            $this->pdo->prepare("UPDATE accounting_moves SET state='posted',posted_by=:actor,posted_at=UTC_TIMESTAMP() WHERE id=:id")->execute(['actor'=>$actorId,'id'=>$moveId]);$this->pdo->prepare('UPDATE vendor_bank_statement_matches SET accounting_move_id=:move WHERE id=:id')->execute(['move'=>$moveId,'id'=>$matchId]);
            $this->pdo->prepare("UPDATE vendor_payments SET state='paid',paid_at=UTC_TIMESTAMP() WHERE id=:id")->execute(['id'=>$paymentId]);
            $paidQ=$this->pdo->prepare("SELECT COALESCE(SUM(a.amount),0) FROM vendor_bill_payment_allocations a JOIN vendor_payments vp ON vp.id=a.payment_id WHERE a.vendor_bill_id=:bill AND vp.state='paid'");$paidQ->execute(['bill'=>$payment['vendor_bill_id']]);$paid=$this->minor((string)$paidQ->fetchColumn(),$places);$credited=$this->minor((string)$payment['amount_credited'],$places);$billTotal=$this->minor((string)$payment['total_amount'],$places);$residual=$this->minor((string)$payment['amount_residual'],$places);$amountPaid=$this->minor((string)$payment['amount_paid'],$places);$status=$residual===0?($paid+$credited>=$billTotal?'paid':'in_payment'):($amountPaid+$credited>0?'partial':'not_paid');
            $this->pdo->prepare('UPDATE vendor_bills SET payment_state=:state WHERE id=:id')->execute(['state'=>$status,'id'=>$payment['vendor_bill_id']]);
            $this->audit((int)$payment['company_id'],$actorId,$matchId,'vendor_bank_statement_match','vendor_payment_reconciled',null,['payment_id'=>$paymentId,'vendor_bill_id'=>$payment['vendor_bill_id'],'reference'=>$reference,'amount'=>$amount,'accounting_move_id'=>$moveId],$ip);
            if($statementLineId!==null){$statementIdQuery=$this->pdo->prepare('SELECT statement_id FROM bank_statement_lines WHERE id=:id');$statementIdQuery->execute(['id'=>$statementLineId]);\Erp\Modules\Accounting\BankStatementRepository::refreshStatementState($this->pdo,(int)$statementIdQuery->fetchColumn());}
            $this->pdo->commit();
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
        return $this->findBill((int)$payment['vendor_bill_id'],$user,$auth)??throw new InvalidArgumentException('Payment was reconciled but vendor bill could not be reloaded.');
    }

    private function prepareLines(array $input,int $companyId): array
    {
        if(count($input)>500)throw new InvalidArgumentException('An RFQ can contain at most 500 product lines.');$result=[];
        foreach(array_values($input) as $index=>$row){if(!is_array($row))throw new InvalidArgumentException('Each Purchase line must be an object.');$unknown=array_diff(array_keys($row),['product_id','uom_id','description','quantity','unit_price','discount_percent','tax_id']);if($unknown)throw new InvalidArgumentException('Unsupported Purchase line fields: '.implode(', ',$unknown));$productId=$this->positiveId($row['product_id']??null,'Product');$q=$this->pdo->prepare('SELECT p.name,p.product_type,p.uom_id,p.purchase_uom_id,p.purchase_ok,p.active,u.category_id FROM products p JOIN units_of_measure u ON u.id=p.purchase_uom_id WHERE p.id=:id AND p.company_id=:company');$q->execute(['id'=>$productId,'company'=>$companyId]);$product=$q->fetch();if(!$product||!(int)$product['active']||!(int)$product['purchase_ok'])throw new InvalidArgumentException('Purchase lines must use an active, purchasable product from this company.');$uomId=$this->positiveId($row['uom_id']??$product['purchase_uom_id'],'Unit of Measure');$uom=$this->pdo->prepare('SELECT category_id,company_id,active FROM units_of_measure WHERE id=:id');$uom->execute(['id'=>$uomId]);$unit=$uom->fetch();if(!$unit||!(int)$unit['active']||(int)$unit['category_id']!==(int)$product['category_id']||($unit['company_id']!==null&&(int)$unit['company_id']!==$companyId))throw new InvalidArgumentException('Each Purchase line must use an active Unit in the product Unit category.');$qty=$this->decimal($row['quantity']??null,'Quantity',6);if((float)$qty<=0)throw new InvalidArgumentException('Purchase quantity must be greater than zero.');$price=$this->decimal($row['unit_price']??0,'Unit Price',6);$discount=$this->decimal($row['discount_percent']??0,'Discount',4);if((float)$discount>100)throw new InvalidArgumentException('Discount cannot exceed 100%.');$taxId=$this->nullableId($row['tax_id']??null,'Purchase Tax');$tax=null;if($taxId){$t=$this->pdo->prepare('SELECT id,name,amount,price_included,account_id FROM purchase_taxes WHERE id=:id AND company_id=:company AND active=1');$t->execute(['id'=>$taxId,'company'=>$companyId]);$tax=$t->fetch();if(!$tax)throw new InvalidArgumentException('Select an active Purchase tax for this company.');if((float)$tax['amount']>0&&empty($tax['account_id']))throw new InvalidArgumentException('Selected Purchase tax needs a Recoverable Tax account.');}$description=$this->text($row['description']??$product['name'],'Description',500)??$product['name'];$gross=round((float)$qty*(float)$price*(1-(float)$discount/100),6);$rate=(float)($tax['amount']??0);$included=(int)($tax['price_included']??0);$taxAmount=$included&&$rate>0?$gross-($gross/(1+$rate/100)):$gross*$rate/100;$subtotal=$included?$gross-$taxAmount:$gross;$total=$included?$gross:$gross+$taxAmount;$result[]=['product_id'=>$productId,'uom_id'=>$uomId,'description'=>$description,'quantity'=>$qty,'unit_price'=>$price,'discount_percent'=>$discount,'tax_id'=>$taxId,'tax_name'=>$tax['name']??null,'tax_rate'=>number_format($rate,4,'.',''),'tax_included'=>$included,'subtotal'=>number_format($subtotal,6,'.',''),'tax_amount'=>number_format($taxAmount,6,'.',''),'total'=>number_format($total,6,'.',''),'product_type'=>$product['product_type'],'sequence'=>($index+1)*10];}
        return $result;
    }

    private function supplier(int $id,int $company): array{$q=$this->pdo->prepare('SELECT id,name,company_id,supplier,buyer_user_id,supplier_payment_terms_id,supplier_currency_code,payable_account_id FROM contacts WHERE id=:id AND active=1 AND supplier=1 AND (company_id IS NULL OR company_id=:company)');$q->execute(['id'=>$id,'company'=>$company]);$v=$q->fetch();if(!$v)throw new InvalidArgumentException('Select an active Supplier Contact shared with or belonging to this company.');return $v;}
    private function warehouse(int $id,int $company):void{$q=$this->pdo->prepare('SELECT 1 FROM warehouses WHERE id=:id AND company_id=:company AND active=1');$q->execute(['id'=>$id,'company'=>$company]);if(!$q->fetchColumn())throw new InvalidArgumentException('Select an active Warehouse from this company.');}
    private function warehouseStockLocation(int $warehouse,int $company):int{$q=$this->pdo->prepare("SELECT id FROM stock_locations WHERE company_id=:company AND warehouse_id=:warehouse AND active=1 AND location_usage='internal' ORDER BY id LIMIT 1 FOR UPDATE");$q->execute(['company'=>$company,'warehouse'=>$warehouse]);$id=$q->fetchColumn();if($id===false)throw new InvalidArgumentException('The receiving Warehouse needs an active Internal stock location.');return(int)$id;}
    private function vendorLocation(int $company):int{$q=$this->pdo->prepare("SELECT id FROM stock_locations WHERE company_id=:company AND warehouse_id IS NULL AND active=1 AND location_usage='vendor' ORDER BY id LIMIT 1");$q->execute(['company'=>$company]);$id=$q->fetchColumn();if($id!==false)return(int)$id;$this->pdo->prepare("INSERT INTO stock_locations (company_id,name,complete_name,location_usage) VALUES (:company,'Vendors','Partners/Vendors','vendor')")->execute(['company'=>$company]);return(int)$this->pdo->lastInsertId();}
    private function paymentTerms(int $id,int $company):array{$q=$this->pdo->prepare('SELECT id,name,due_days FROM payment_terms WHERE id=:id AND active=1 AND (company_id IS NULL OR company_id=:company)');$q->execute(['id'=>$id,'company'=>$company]);$v=$q->fetch();if(!$v)throw new InvalidArgumentException('Select active payment terms available to this company.');return $v;}
    private function assertCompanyUser(int $user,int $company):void{$q=$this->pdo->prepare("SELECT 1 FROM users u JOIN user_company_access a ON a.user_id=u.id WHERE a.user_id=:user AND a.company_id=:company AND u.status IN ('confirmed','active')");$q->execute(['user'=>$user,'company'=>$company]);if(!$q->fetchColumn())throw new InvalidArgumentException('Buyer must be an active user with access to this company.');}
    private function companyCurrency(int $company):string{$q=$this->pdo->prepare('SELECT currency_code FROM companies WHERE id=:id AND active=1');$q->execute(['id'=>$company]);$v=$q->fetchColumn();if(!$v)throw new InvalidArgumentException('Company is inactive or unavailable.');return(string)$v;}
    private function account(int $id,int $company):?array{if($id<1)return null;$q=$this->pdo->prepare('SELECT id,code,name,account_type FROM accounting_accounts WHERE id=:id AND company_id=:company AND active=1');$q->execute(['id'=>$id,'company'=>$company]);return$q->fetch()?:null;}
    private function company(UserContext $user,Authorization $auth,mixed $raw):int{$id=$raw===null||$raw===''?($user->defaultCompanyId??(count($user->companyIds)===1?$user->companyIds[0]:null)):$this->positiveId($raw,'Company');if(!$id||!$auth->canAccessCompany($id))throw new InvalidArgumentException('Select an allowed company.');return$id;}
    private function positiveId(mixed $v,string $label):int{$id=filter_var($v,FILTER_VALIDATE_INT);if($id===false||$id<1)throw new InvalidArgumentException($label.' must be a positive integer.');return$id;}
    private function nullableId(mixed $v,string $label):?int{return$v===null||$v===''?null:$this->positiveId($v,$label);}
    private function text(mixed $v,string $label,int $max):?string{$s=trim((string)($v??''));if($s==='' )return null;if(mb_strlen($s)>$max)throw new InvalidArgumentException($label.' must be '.$max.' characters or fewer.');return$s;}
    private function date(mixed $v,string $label):string{$s=trim((string)($v??''));$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$s);if(!$d||$d->format('Y-m-d')!==$s)throw new InvalidArgumentException($label.' must be YYYY-MM-DD.');return$s;}
    private function nullableDate(mixed $v,string $label):?string{return$v===null||$v===''?null:$this->date($v,$label);}
    private function boolean(mixed $v,string $label):bool{if(!is_bool($v)&&!in_array($v,[0,1,'0','1','true','false'],true))throw new InvalidArgumentException($label.' must be true or false.');$x=filter_var($v,FILTER_VALIDATE_BOOLEAN,FILTER_NULL_ON_FAILURE);if($x===null)throw new InvalidArgumentException($label.' must be true or false.');return$x;}
    private function decimal(mixed $v,string $label,int $scale):string{$s=trim((string)($v??''));if(!preg_match('/^(0|[1-9][0-9]{0,11})(?:\.([0-9]{1,6}))?$/D',$s))throw new InvalidArgumentException($label.' must be a nonnegative decimal number.');return number_format((float)$s,$scale,'.','');}
    private function add(string $a,string $b):string{return number_format((float)$a+(float)$b,6,'.','');}
    private function subtract(string $a,string $b):string{return number_format((float)$a-(float)$b,6,'.','');}
    private function mul(string $total,string $quantity,string $ordered):string{if((float)$ordered<=0)return'0.000000';return number_format((float)$total*(float)$quantity/(float)$ordered,6,'.','');}
    private function minor(string $amount,int $places):int{if(!preg_match('/^(0|[1-9][0-9]{0,11})(?:\.([0-9]{1,6}))?$/D',$amount,$m))throw new InvalidArgumentException('Amounts must be nonnegative and below 1 trillion in the company currency.');$factor=10**$places;$fraction=str_pad($m[2]??'', $places+1,'0');$minor=(int)$m[1]*$factor+(int)substr($fraction,0,$places);if((int)($fraction[$places]??'0')>=5)$minor++;return$minor;}
    private function decimalFromMinor(int $amount,int $places):string{$factor=10**$places;return intdiv($amount,$factor).'.'.str_pad((string)($amount%$factor),$places,'0',STR_PAD_LEFT);}
    private function nextRfqNumber(int $company,int $year):string{$this->pdo->prepare('INSERT INTO purchase_order_sequences (company_id,sequence_year,last_rfq_number,last_po_number) VALUES (:company,:year,0,0) ON DUPLICATE KEY UPDATE company_id=VALUES(company_id)')->execute(['company'=>$company,'year'=>$year]);$q=$this->pdo->prepare('SELECT last_rfq_number FROM purchase_order_sequences WHERE company_id=:company AND sequence_year=:year FOR UPDATE');$q->execute(['company'=>$company,'year'=>$year]);$n=(int)$q->fetchColumn()+1;$this->pdo->prepare('UPDATE purchase_order_sequences SET last_rfq_number=:n WHERE company_id=:company AND sequence_year=:year')->execute(['n'=>$n,'company'=>$company,'year'=>$year]);return sprintf($this->documentPrefix($company,'purchase_rfq','RFQ').'%04d-%05d',$year,$n);}
    private function nextPoNumber(int $company,int $year):string{$q=$this->pdo->prepare('SELECT last_po_number FROM purchase_order_sequences WHERE company_id=:company AND sequence_year=:year FOR UPDATE');$q->execute(['company'=>$company,'year'=>$year]);$n=(int)$q->fetchColumn()+1;$this->pdo->prepare('UPDATE purchase_order_sequences SET last_po_number=:n WHERE company_id=:company AND sequence_year=:year')->execute(['n'=>$n,'company'=>$company,'year'=>$year]);return sprintf($this->documentPrefix($company,'purchase_order','PO').'%04d-%05d',$year,$n);}
    private function billOrdinal(int $order):int{$q=$this->pdo->prepare('SELECT COUNT(*) FROM vendor_bills WHERE purchase_order_id=:order');$q->execute(['order'=>$order]);return(int)$q->fetchColumn()+1;}
    private function nextBillNumber(int $company,int $year):string{$this->pdo->prepare('INSERT INTO vendor_bill_sequences (company_id,sequence_year,last_number) VALUES (:company,:year,0) ON DUPLICATE KEY UPDATE company_id=VALUES(company_id)')->execute(['company'=>$company,'year'=>$year]);$q=$this->pdo->prepare('SELECT last_number FROM vendor_bill_sequences WHERE company_id=:company AND sequence_year=:year FOR UPDATE');$q->execute(['company'=>$company,'year'=>$year]);$n=(int)$q->fetchColumn()+1;$this->pdo->prepare('UPDATE vendor_bill_sequences SET last_number=:n WHERE company_id=:company AND sequence_year=:year')->execute(['n'=>$n,'company'=>$company,'year'=>$year]);return sprintf($this->documentPrefix($company,'vendor_bill','BILL').'%04d-%05d',$year,$n);}

    private function documentPrefix(int $company,string $sequenceKey,string $default):string{$query=$this->pdo->prepare('SELECT prefix FROM company_document_prefixes WHERE company_id=:company AND sequence_key=:sequence_key');$query->execute(['company'=>$company,'sequence_key'=>$sequenceKey]);$prefix=$query->fetchColumn();return $prefix===false?$default:(string)$prefix;}
