    private function nextVendorCreditNoteRefundNumber(int $company,int $year):string{$this->pdo->prepare('INSERT INTO vendor_credit_note_refund_sequences (company_id,sequence_year,last_number) VALUES (:company,:year,0) ON DUPLICATE KEY UPDATE company_id=VALUES(company_id)')->execute(['company'=>$company,'year'=>$year]);$q=$this->pdo->prepare('SELECT last_number FROM vendor_credit_note_refund_sequences WHERE company_id=:company AND sequence_year=:year FOR UPDATE');$q->execute(['company'=>$company,'year'=>$year]);$n=(int)$q->fetchColumn()+1;$this->pdo->prepare('UPDATE vendor_credit_note_refund_sequences SET last_number=:n WHERE company_id=:company AND sequence_year=:year')->execute(['n'=>$n,'company'=>$company,'year'=>$year]);return sprintf('VCRF%04d-%05d',$year,$n);}
    private function nextVendorPaymentNumber(int $company,int $year):string{$this->pdo->prepare('INSERT INTO vendor_payment_sequences (company_id,sequence_year,last_number) VALUES (:company,:year,0) ON DUPLICATE KEY UPDATE company_id=VALUES(company_id)')->execute(['company'=>$company,'year'=>$year]);$q=$this->pdo->prepare('SELECT last_number FROM vendor_payment_sequences WHERE company_id=:company AND sequence_year=:year FOR UPDATE');$q->execute(['company'=>$company,'year'=>$year]);$n=(int)$q->fetchColumn()+1;$this->pdo->prepare('UPDATE vendor_payment_sequences SET last_number=:n WHERE company_id=:company AND sequence_year=:year')->execute(['n'=>$n,'company'=>$company,'year'=>$year]);return sprintf('VPAY%04d-%05d',$year,$n);}
    private function orderAudit(array $order):array{return['state'=>$order['state'],'partner_contact_id'=>$order['partner_contact_id'],'vendor_reference'=>$order['vendor_reference'],'arrival_confirmation'=>(bool)($order['arrival_confirmation']??false),'total_amount'=>$order['total_amount']];}
    private function audit(int $company,int $actor,int $record,string $model,string $event,?array $old,array $new,string $remote):void{$ip=filter_var($remote,FILTER_VALIDATE_IP)?inet_pton($remote):null;$q=$this->pdo->prepare('INSERT INTO audit_events (company_id,user_id,event_key,model_key,record_id,old_values,new_values,ip_address) VALUES (:company,:user,:event,:model,:record,:old_values,:new_values,:ip)');$q->bindValue(':company',$company,PDO::PARAM_INT);$q->bindValue(':user',$actor,PDO::PARAM_INT);$q->bindValue(':event',$event);$q->bindValue(':model',$model);$q->bindValue(':record',$record,PDO::PARAM_INT);$q->bindValue(':old_values',$old===null?null:json_encode($old,JSON_THROW_ON_ERROR),$old===null?PDO::PARAM_NULL:PDO::PARAM_STR);$q->bindValue(':new_values',json_encode($new,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$q->bindValue(':ip',$ip,$ip===null?PDO::PARAM_NULL:PDO::PARAM_LOB);$q->execute();}
}
